"""Data-driven adventure game engine.

A `World` is loaded from JSON and manipulated purely functionally:
every command maps a State to a new State, so the solver can explore
the state space without mutating anything.
"""
from __future__ import annotations

import json
from dataclasses import dataclass
from functools import cached_property


@dataclass(frozen=True)
class State:
    room: str
    inventory: frozenset[str]
    unlocked: frozenset[str]  # door ids, one per directed exit: "room/dir"


class World:
    def __init__(self, data: dict):
        self.rooms: dict = data["rooms"]
        self.start: str = data["start"]
        self.win_room: str = data["win"]["room"]
        self.win_item: str | None = data["win"].get("item")
        for name, room in self.rooms.items():
            for direction, exit_ in room["exits"].items():
                assert exit_["to"] in self.rooms, f"exit {name}/{direction} -> unknown room"

    @classmethod
    def load(cls, path: str) -> "World":
        with open(path) as f:
            return cls(json.load(f))

    @cached_property
    def initial_state(self) -> State:
        return State(self.start, frozenset(), frozenset())

    # -- helpers ---------------------------------------------------------

    @staticmethod
    def _door_id(room: str, direction: str) -> str:
        return f"{room}/{direction}"

    def exits(self, room: str) -> dict[str, dict]:
        return self.rooms[room]["exits"]

    def items_here(self, state: State) -> list[str]:
        return [i for i in self.rooms[state.room]["items"] if i not in state.inventory]

    def is_win(self, state: State) -> bool:
        if state.room != self.win_room:
            return False
        return self.win_item is None or self.win_item in state.inventory

    def commands(self, state: State) -> list[str]:
        """All commands legal in this state (deterministic order)."""
        cmds: list[str] = []
        for item in sorted(self.items_here(state)):
            cmds.append(f"take {item}")
        for direction in sorted(self.exits(state.room)):
            cmds.append(f"go {direction}")
        return cmds

    def apply(self, state: State, command: str) -> State | None:
        """Return the successor state, or None if the command is illegal."""
        parts = command.split(maxsplit=1)
        if len(parts) != 2:
            return None
        verb, arg = parts

        if verb == "take":
            if arg not in self.items_here(state):
                return None
            return State(state.room, state.inventory | {arg}, state.unlocked)

        if verb == "go":
            exit_ = self.exits(state.room).get(arg)
            if exit_ is None:
                return None
            key = exit_.get("key")
            unlocked = state.unlocked
            if key is not None:
                door = self._door_id(state.room, arg)
                if key not in state.inventory and door not in state.unlocked:
                    return None  # locked, no key
                unlocked = state.unlocked | {door}
            return State(exit_["to"], state.inventory, unlocked)

        return None

